def query_senza_indice(m):
    cpu = m.get("cpu_pct")
    scan = m.get("select_scan_s")
    if cpu is None or scan is None:
        return None
    join = m.get("select_full_join_s")
    if join is None:
        join = 0
    full = scan + join
    if cpu > 85 and full > 5:
        return diagnosis("query_senza_indice", "critico", "cpu", {"cpu_pct": cpu, "scansioni_complete_s": round(full, 2)}, "CPU satura con molte scansioni complete: trovare le query senza indice (EXPLAIN, log delle slow query) e aggiungere gli indici mancanti.")
    if cpu > 70 and full > 5:
        return diagnosis("query_senza_indice", "attenzione", "cpu", {"cpu_pct": cpu, "scansioni_complete_s": round(full, 2)}, "CPU alta con molte scansioni complete: verificare con EXPLAIN le query pesanti e aggiungere gli indici mancanti.")
    return None

