def contesa_lock_righe(m):
    lock = m.get("lock_ms_s")
    if lock is None:
        return None
    attese = round(lock / 1000, 1)
    if lock > 10000:
        return diagnosis("contesa_lock_righe", "critico", "lock", {"lock_ms_s": lock, "sessioni_in_attesa_stimate": attese}, "Molte sessioni sono bloccate su lock di riga InnoDB. Cerca e chiudi la transazione lunga o non terminata (information_schema.innodb_trx, sys.innodb_lock_waits), poi verifica che l'applicazione faccia COMMIT o ROLLBACK.")
    if lock > 5000:
        return diagnosis("contesa_lock_righe", "attenzione", "lock", {"lock_ms_s": lock, "sessioni_in_attesa_stimate": attese}, "Il tempo di attesa sui lock di riga è sopra la norma. Controlla le transazioni aperte da molto tempo e gli UPDATE che toccano le stesse righe.")
    return None
